import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    factors = []
    for i in range(2, int(math.sqrt(a)) + 1):
        if a % i == 0:
            factors.append(i)
            while a % i == 0:
                a //= i

    if a > 1:
        factors.append(a)

    if len(factors) < 3:
        return False
    else:
        for prime in factors:
            if not is_prime(prime):
                return False
        return True
