def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices.

    Examples:
        >>> add([4, 2, 6, 7])
        2
    """
    even_elements = []
    for i, num in enumerate(lst):
        if i % 2 != 0 and num % 2 == 0:
            even_elements.append(num)
    return sum(even_elements)
