from typing import List

def words_string(s: str) -> List[str]:
    """
    Splits the string into words and returns them as a list.
    """
    words = []
    current_word = ""
    in_quotes = False
    in_number = False
    in_parentheses = False
    for char in s:
        if char == "," or char == " ":
            if in_quotes and not in_parentheses:
                words.append(current_word.strip())
                current_word = ""
            elif in_number and not in_parentheses:
                words.append(current_word.strip())
                current_word = ""
        elif char == '"':
            in_quotes = not in_quotes
        elif char == "(":
            in_parentheses = not in_parentheses
        elif char.isdigit():
            in_number = True
        elif char == ".":
            in_number = False
        current_word += char
    if in_quotes:
        words.append(current_word.strip())
    elif in_number:
        words.append(current_word.strip())
    return words
