from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    n = len(arr)
    i = 0

    while i < n - 1 and arr[i] <= arr[i + 1]:
        i += 1

    if i == n - 1:
        return True

    for j in range(i + 1, n):
        if arr[j] < arr[j - 1]:
            arr = arr[:j] + arr[j + 1:] + [arr[j]]
            return True
        if arr[j] < arr[j - 1]:
            return False

    return True
